def gen(rng):
    def fmt(ops):
        return str(len(ops)) + '\n' + '\n'.join(ops)

    tests = [
        fmt(['most']),
        fmt(['inc 1', 'most']),
        fmt(['dec 1', 'most']),
        fmt(['inc 1000000000', 'inc 1', 'most', 'dec 1', 'most', 'dec 1000000000', 'most']),
        fmt(['inc 5', 'inc 6', 'inc 5', 'inc 6', 'most', 'dec 6', 'most', 'inc 6', 'most']),
        fmt(['inc 3', 'dec 4', 'inc 4', 'most', 'dec 3', 'dec 4', 'most']),
        fmt(['inc 1', 'inc 2', 'inc 3', 'most', 'dec 3', 'most', 'dec 2', 'most', 'dec 1', 'most']),
    ]
    for q in (4, 8, 12, 16, 20, 24):
        for _ in range(3):
            ids = rng.randint(1, 4)
            ops = []
            for _ in range(q - 1):
                r = rng.random()
                if r < 0.35:
                    ops.append('inc ' + str(rng.randint(1, ids)))
                elif r < 0.65:
                    ops.append('dec ' + str(rng.randint(1, ids)))
                else:
                    ops.append('most')
            ops.append('most')
            tests.append(fmt(ops))
    # big: many distinct ids, then most / dec alternating (kills per-query scans)
    ids = rng.sample(range(1, 10**9), 50000)
    ops = ['inc ' + str(i) for i in ids]
    for j in range(25000):
        ops.append('most')
        ops.append('dec ' + str(rng.choice(ids)))
    tests.append(fmt(ops))
    # big: small pool, random mix
    ops = []
    for _ in range(100000):
        r = rng.random()
        if r < 0.4:
            ops.append('inc ' + str(rng.randint(1, 50)))
        elif r < 0.7:
            ops.append('dec ' + str(rng.randint(1, 50)))
        else:
            ops.append('most')
    tests.append(fmt(ops))
    # big: heavy increments on a medium pool, decrement phase
    pool = [rng.randint(1, 10**9) for _ in range(2000)]
    ops = []
    for _ in range(60000):
        ops.append('inc ' + str(rng.choice(pool)))
        if rng.random() < 0.2:
            ops.append('most')
    for _ in range(30000):
        ops.append('dec ' + str(rng.choice(pool)))
        if rng.random() < 0.3:
            ops.append('most')
    ops = ops[:99999] + ['most']
    tests.append(fmt(ops))
    return tests
